class RAII_Resource {
    int* handle;
public:
    // 1. Acquisition (Constructor)
    explicit RAII_Resource(int id) : handle(new int(id)) {}

    // 2. Release (Destructor)
    // Compiler ensures this is called on scope exit.
    ~RAII_Resource() { delete handle; }

    // Disable copy/move for strict ownership
    RAII_Resource(const RAII_Resource&) = delete;
    RAII_Resource& operator=(const RAII_Resource&) = delete;
};

void scope_exit_demo() {
    RAII_Resource r1(10); 

    if (needs_early_exit) {
        return; // r1.~RAII_Resource() is guaranteed here.
    } 

    RAII_Resource r2(20);
    // ... code ...

} // r2.~RAII_Resource() then r1.~RAII_Resource() (LIFO)
